package com.yonlab.vision;
import android.app.Activity;import android.content.*;import android.os.Bundle;import android.widget.*;
/** Actual tool entry points; does not launch the legacy demo applications. */
public final class LabToolsActivity extends YOnActivity {
 public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BACK);LinearLayout header=Ui.brandHeader(this,"도구 모음");header.addView(Ui.secondary(this,"닫기",v->finish()),new LinearLayout.LayoutParams(Ui.dp(this,72),Ui.dp(this,48)));root.addView(header);ScrollView scroll=new ScrollView(this);LinearLayout content=Ui.column(this);scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);String[][] tools={{"qr","QR · 바코드","사진에서 읽고 QR을 만드세요","credit-card"},{"ocr","텍스트 읽기","사진의 한글과 영문을 읽으세요","image"},{"pet","반려동물","사진에서 개와 고양이를 찾으세요","paw"},{"ball","공 탐지","사진에서 운동용 공을 찾으세요","search"},{"pose","자세 분석","사진의 자세 지점을 살펴보세요","pulse"},{"device","디바이스 도구","화면 · 소리 · 조명 · 촬영","settings"},{"cloud","명령 연결","설정한 MQTT 연결을 관리하세요","external-link"},{"cloudrpc","원격 제어","명령을 받고 촬영 결과를 연결하세요","external-link"},{"voice","음성 입출력","말을 글로 바꾸고 문장을 읽으세요","volume-2"},{"offlinevoice","한국어 음성 인식","말과 음성 파일을 글로 읽으세요","volume-2"},{"ipc","앱 연결","AXSL Vision 앱 사이에서 결과를 연결하세요","external-link"}};
  for(int i=0;i<tools.length;i+=2){LinearLayout row=new LinearLayout(this);for(int j=i;j<Math.min(i+2,tools.length);j++){String[] t=tools[j];LinearLayout card=Ui.panel(this);LinearLayout heading=new LinearLayout(this);heading.addView(Ui.icon(this,t[3],24));TextView title=Ui.heading(this,t[1],20);title.setPadding(Ui.dp(this,10),0,0,0);heading.addView(title);card.addView(heading);TextView copy=Ui.text(this,t[2],14);copy.setTextColor(Ui.MUTED);card.addView(copy);card.addView(Ui.button(this,"열기",v->open(t[0])));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(Ui.dp(this,5),0,Ui.dp(this,5),Ui.dp(this,12));row.addView(card,p);}if(i==tools.length-1)row.addView(new LinearLayout(this),new LinearLayout.LayoutParams(0,1,1));content.addView(row);}}
 private void open(String tool){String activity="device".equals(tool)?"DeviceToolsActivity":"cloud".equals(tool)?"CloudActivity":"voice".equals(tool)?"VoiceActivity":"ipc".equals(tool)?"IpcActivity":"ToolPhotoActivity";try{startActivity(new Intent().setClassName(this,"cloudrpc".equals(tool)?"com.yonlab.cloudrpc.CloudRpcActivity":"offlinevoice".equals(tool)?"com.yonlab.offlinevoice.OfflineVoiceActivity":"com.yonlab.vision."+activity).putExtra("tool",tool));}catch(ActivityNotFoundException e){Ui.error(this,"도구를 열 수 없습니다",e);}}
}
